const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const cf=($('Resolve Base').first().json.fields)||{};
const att=(f['Attachment']&&f['Attachment'][0])||null;
if(!att||!att.url){ throw new Error('Launch guard: launch record '+rec.id+' has no CSV file in the Attachment field. Nothing was written.'); }
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Table ID': ((f['Table ID']||f['Target']||'')+'').trim(),
  'Key column': ((f['Key Column']||'Domain')+'').trim(),
  'Fields to attach': ((f['Fields to Attach']||'')+'').trim(),
  _attachmentUrl: att.url,
  _launchRecordId: rec.id,
  submittedAt: new Date().toISOString()
} }];

const j=$('Launch Params').first().json;
const bin=$input.first().binary||{};
const key=bin['Domain_CSV'] ? 'Domain_CSV' : Object.keys(bin)[0];
if(!key){ throw new Error('Launch guard: CSV download returned no file. Nothing was written.'); }
return [{ json: j, binary: { Domain_CSV: bin[key] } }];

const p=$('Merge Launch').first().json;
const baseId=String(p['Clayroots Base ID']||'').trim();
const tableId=String(p['Table ID']||'').trim();
const keyName=(String(p['Key column']||p['Key Column']||'Domain').trim())||'Domain';
const fieldsRaw=String(p['Fields to attach']||p['Fields to Attach']||'').trim();
// Allowed keys must be unique per row in the target table. Contact Key is the ContaGen/Supersoniq
// upsert key (first+last+domain), so it is row-unique on contacts tables.
const ALLOWED_KEYS=['Domain','Final Email','Contact Key'];
if(!ALLOWED_KEYS.includes(keyName)){ throw new Error('Key guard: Key column "'+keyName+'" is not one of '+ALLOWED_KEYS.join(' / ')+'. Nothing was written.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(baseId)){ throw new Error('Head guard: Clayroots Base ID "'+baseId+'" is not a valid Airtable base id (appXXXXXXXXXXXXXX). Nothing was written.'); }
if(!/^tbl[A-Za-z0-9]{14}$/.test(tableId)){ throw new Error('Head guard: Table ID "'+tableId+'" is not a valid Airtable table id (tblXXXXXXXXXXXXXX). Nothing was written.'); }
const rows=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length>0);
if(rows.length===0){ throw new Error('Head guard: the uploaded CSV parsed to zero data rows. Nothing was written.'); }
const headers=Object.keys(rows[0]);
let keyHeader=headers.find(h=>h.trim()===keyName);
let headerNote='';
if(!keyHeader){ keyHeader=headers.find(h=>h.trim().toLowerCase()===keyName.toLowerCase()); if(keyHeader){ headerNote='case-variant header "'+keyHeader+'" accepted as '+keyName; } }
if(!keyHeader){ throw new Error('Head guard: no "'+keyName+'" column in the CSV. Headers found: '+headers.join(', ')+'. Nothing was written.'); }
let attrCols=headers.filter(h=>h!==keyHeader);
if(attrCols.length===0){ throw new Error('Head guard: the CSV has only the '+keyName+' column and no attribute columns to merge. Headers found: '+headers.join(', ')+'. Nothing was written.'); }
let fieldsRequested=[]; let fieldsSkipped=[];
if(fieldsRaw){
  fieldsRequested=fieldsRaw.split(',').map(s=>s.trim()).filter(s=>s.length>0);
  if(fieldsRequested.length===0){ throw new Error('Head guard: Fields to attach was set but parsed to zero field names. Nothing was written.'); }
  const byExact=new Set(attrCols);
  const byLower={}; for(const c of attrCols){ byLower[c.toLowerCase()]=c; }
  const picked=[];
  for(const want of fieldsRequested){ if(byExact.has(want)){ picked.push(want); } else if(byLower[want.toLowerCase()]){ picked.push(byLower[want.toLowerCase()]); } else { fieldsSkipped.push(want); } }
  const uniq=[...new Set(picked)];
  if(uniq.length===0){ throw new Error('Head guard: none of the requested Fields to attach ('+fieldsRequested.join(', ')+') exist as CSV columns. CSV attribute columns: '+attrCols.join(', ')+'. Nothing was written.'); }
  attrCols=uniq;
}
const flat=v=>{ if(v===null||v===undefined) return ''; if(Array.isArray(v)) return v.map(x=>String(x)).join(', '); if(typeof v==='object') return JSON.stringify(v); return String(v); };
const lookup={};
let dupKeys=0;
for(const r of rows){ const k=flat(r[keyHeader]).trim().toLowerCase(); if(!k) continue; if(lookup[k]) dupKeys++; const attrs={}; for(const c of attrCols){ attrs[c]=flat(r[c]).trim(); } lookup[k]=attrs; }
const distinctKeys=Object.keys(lookup).length;
if(distinctKeys===0){ throw new Error('Head guard: every CSV row has an empty '+keyName+' value. Nothing was written.'); }
return [{ json: { baseId, tableId, keyName, fieldsRequested, fieldsSkipped, launchRecordId: p._launchRecordId||'', launchedVia: p._launchRecordId ? 'record' : 'form', startedAt: p.submittedAt||new Date().toISOString(), csvRows: rows.length, distinctKeys, dupKeys, keyHeader, headerNote, attrCols, lookup } }];

const v=$('Validate & Build Lookup').first().json;
const tables=($input.first().json.tables)||[];
const table=tables.find(t=>t.id===v.tableId);
if(!table){ throw new Error('Head guard: table '+v.tableId+' does not exist in base '+v.baseId+'. Tables there: '+tables.map(t=>t.id+' ('+t.name+')').join(', ')+'. Nothing was written.'); }
if(v.keyName==='Final Email' && /domains/i.test(table.name)){ throw new Error('Key guard: Final Email merges target contact-shaped tables only, and "'+table.name+'" is a Domains table (domains tables carry Final Email from the public-emails waterfall, but their rows are companies, not contacts). Nothing was written.'); }
const fieldNames=(table.fields||[]).map(f=>f.name);
if(!fieldNames.includes(v.keyName)){ throw new Error('Head guard: table "'+table.name+'" ('+v.tableId+') has no field named exactly "'+v.keyName+'". Fields: '+fieldNames.join(', ')+'. Nothing was written.'); }
// Airtable field names are case-insensitive: map CSV columns onto existing fields case-insensitively so a case-variant header fills the existing column instead of colliding on create.
const byLower={}; for(const n of fieldNames){ byLower[n.toLowerCase()]=n; }
const renames={}; const canonical=[]; const notes=[];
for(const c of v.attrCols){
  if(fieldNames.includes(c)){ canonical.push(c); continue; }
  const hit=byLower[c.toLowerCase()];
  if(hit){ renames[c]=hit; canonical.push(hit); notes.push('CSV column "'+c+'" mapped to existing field "'+hit+'"'); }
  else { canonical.push(c); }
}
const seen={}; const dupes=[];
for(const c of canonical){ if(seen[c]) dupes.push(c); seen[c]=true; }
if(dupes.length){ throw new Error('Head guard: multiple CSV columns map to the same table field after case-insensitive matching: '+[...new Set(dupes)].join(', ')+'. Rename the CSV columns so each targets one field. Nothing was written.'); }
let lookup=v.lookup;
if(Object.keys(renames).length){
  const renamed={};
  for(const k of Object.keys(lookup)){ const attrs=lookup[k]; const out={}; for(const c of Object.keys(attrs)){ out[renames[c]||c]=attrs[c]; } renamed[k]=out; }
  lookup=renamed;
}
const missingFields=canonical.filter(c=>!fieldNames.includes(c));
const headerNote=[v.headerNote, notes.join('; ')].filter(Boolean).join(' • ');
return [{ json: Object.assign({}, v, { tableName: table.name, attrCols: canonical, lookup, missingFields, headerNote }) }];

const g=$('Guard Schema').first().json;
const tables=($input.first().json.tables)||[];
const table=tables.find(t=>t.id===g.tableId);
const names=((table&&table.fields)||[]).map(f=>f.name);
const still=g.attrCols.filter(c=>!names.includes(c));
if(still.length>0){ throw new Error('Field creation failed: these CSV columns are still missing on the table after create: '+still.join(', ')+'. No row was modified.'); }
return [{ json: { fieldsVerified: true, created: g.missingFields } }];

const g=$('Guard Schema').first().json;
const lookup=g.lookup;
const out=[];
for(const item of $input.all()){ const j=item.json; const f=j.fields||{}; const k=String(f[g.keyName]||'').trim().toLowerCase(); if(!k) continue; const attrs=lookup[k]; if(!attrs) continue; out.push({ json: Object.assign({ id: j.id }, attrs) }); }
if(out.length===0){ return [{ json: { _zeroMatch: true, _tableRowsScanned: $input.all().length } }]; }
return out;

const g=$('Guard Schema').first().json;
const items=$input.all();
const zero=items.length===1 && items[0].json && items[0].json._zeroMatch===true;
let rowsMatched=0, rowsUpdated=0, writeFailures=0, tableRowsScanned=0;
if(zero){ tableRowsScanned=items[0].json._tableRowsScanned||0; }
else {
  const failed=items.filter(i=>i.json&&i.json.error);
  writeFailures=failed.length;
  rowsMatched=items.length;
  rowsUpdated=items.length-writeFailures;
  if(rowsUpdated===0){ throw new Error('All '+items.length+' row updates failed. First error: '+JSON.stringify(failed[0]&&failed[0].json.error)); }
  tableRowsScanned=$('Get Table Rows').all().length;
}
const matched={};
if(!zero){ for(const it of $('Get Table Rows').all()){ const f=it.json.fields||{}; const k=String(f[g.keyName]||'').trim().toLowerCase(); if(k&&g.lookup[k]) matched[k]=true; } }
const unmatched=Object.keys(g.lookup).filter(k=>!matched[k]);
return [{ json: { baseId: g.baseId, tableId: g.tableId, tableName: g.tableName, keyName: g.keyName, fieldsRequested: g.fieldsRequested||[], fieldsSkipped: g.fieldsSkipped||[], launchedVia: g.launchedVia, startedAt: g.startedAt, headerNote: g.headerNote, csvRows: g.csvRows, distinctKeys: g.distinctKeys, dupKeys: g.dupKeys, fieldsAppended: g.attrCols, fieldsCreated: g.missingFields, tableRowsScanned, rowsMatched, rowsUpdated, writeFailures, unmatchedCount: unmatched.length, unmatchedSample: unmatched.slice(0, 20), zeroMatch: zero } }];

const s=$('Collect Results').first().json;
let clientRec=[];
try{ const lc=$('Fetch Launch Record').first().json.fields.Client; if(Array.isArray(lc)&&lc.length&&lc[0]) clientRec=[lc[0]]; }catch(e){}
if(!clientRec.length){ try{ const rc=$('Resolve Client').first().json; if(rc&&rc.id) clientRec=[rc.id]; }catch(e){} }
let dur=0;
try{ if(s.startedAt) dur=Math.max(0, Math.round(($now.toMillis()-new Date(s.startedAt).getTime())/1000)); }catch(e){}
const status=s.writeFailures ? 'Succeeded with errors' : 'Succeeded';
const fmt=v=>Number(v||0).toLocaleString('en-US');
const parts=[];
parts.push('**'+fmt(s.rowsUpdated)+' rows updated of '+fmt(s.csvRows)+' CSV rows**');
parts.push('**Fields**\n- **Key:** '+s.keyName+'\n- **Requested:** '+((s.fieldsRequested&&s.fieldsRequested.length) ? s.fieldsRequested.join(', ')+(s.fieldsSkipped.length ? ' (skipped, not in CSV: '+s.fieldsSkipped.join(', ')+')' : '') : 'all non-key CSV columns')+'\n- **Appended:** '+s.fieldsAppended.join(', ')+'\n- **Created:** '+(s.fieldsCreated.length ? s.fieldsCreated.join(', ') : 'none'));
parts.push('**Rows**\n- **CSV rows:** '+fmt(s.csvRows)+'\n- **Distinct CSV keys:** '+fmt(s.distinctKeys)+'\n- **Duplicate keys in CSV:** '+fmt(s.dupKeys)+'\n- **Table rows scanned:** '+fmt(s.tableRowsScanned)+'\n- **Matched:** '+fmt(s.rowsMatched)+'\n- **Updated:** '+fmt(s.rowsUpdated)+'\n- **Write failures:** '+fmt(s.writeFailures)+'\n- **Unmatched CSV keys:** '+fmt(s.unmatchedCount)+(s.unmatchedSample.length ? ' (e.g. '+s.unmatchedSample.join(', ')+')' : ''));
parts.push('**Launched via:** '+s.launchedVia+(s.headerNote ? ' · '+s.headerNote : ''));
const desc=parts.join('\n\n');
const out={
  'Automation': 'Append fields to table',
  'Status': status,
  'Trigger': 'form',
  'Run at': $now.toISO(),
  'Client': clientRec,
  'Target': s.tableName+' ('+s.tableId+')',
  'Table ID': s.tableId,
  'Key Column': s.keyName,
  'Records In': s.csvRows,
  'Records Out': s.rowsUpdated,
  'Errors': s.writeFailures,
  'Duration s': dur,
  'Description': desc,
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(!clientRec.length){ delete out['Client']; }
return [{ json: out }];
